const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define regions (simplified bounding boxes for Northern and Southern Taiwan)
  const northTaiwan = ee.Geometry.Rectangle([120, 25.3, 122, 24.5]); // Rough bounds
  const southTaiwan = ee.Geometry.Rectangle([120, 22.5, 121, 21.9]); // Rough bounds

  // 2. Date range
  const startDate = '2009-08-03';
  const endDate = '2009-08-10'; // Exclusive

  // 3. Get TRMM precipitation data (available for 2009)
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(ee.Geometry.Point([120.5, 23.5])); // Central point for Taiwan

  // Check collection size
  const collSize = chirps.size().getInfo();
  console.log(`CHIRPS images found: ${collSize} (Expected: 7)`);

  if (collSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Sum precipitation over the week
  const totalPrecip = chirps.sum();

  // 5. Calculate mean precipitation for each region
  const northStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northTaiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const southStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southTaiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  // Get pixel counts to check for valid data
  const northCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northTaiwan,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const southCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southTaiwan,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`North pixels: ${northCount}, South pixels: ${southCount}`);

  if (northCount === 0 || southCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Get mean values
  const northMean = northStats.get('precipitation').getInfo();
  const southMean = southStats.get('precipitation').getInfo();

  console.log(`North mean weekly rainfall: ${northMean ? northMean.toFixed(2) : 'null'} mm`);
  console.log(`South mean weekly rainfall: ${southMean ? southMean.toFixed(2) : 'null'} mm`);

  // 7. Validate results
  if (northMean === null || southMean === null || 
      isNaN(northMean) || isNaN(southMean) ||
      northMean > 1000 || southMean > 1000) { // Unreasonable precipitation values
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Compare and output answer
  if (southMean > northMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

